+    assert!(!nc_path.exists(), "blocked bypass must not write NC file");
+
+    h.state_mut().state.ai_chat.cancel();
+    pump_until_idle(&mut h);
+    let _ = std::fs::remove_dir_all(&tmp_dir);
+}
